<script setup>
import { computed, nextTick, onMounted, onUnmounted, ref } from 'vue'
import { api, date, notify, state } from '../lib'
import Icon from './Icon.vue'
import Modal from './Modal.vue'
import ProviderIcon from './ProviderIcon.vue'
import VisitPath from './VisitPath.vue'
import { entryIcon } from '../file-icon'
import { changedNameParts } from '../name-diff'
import { useVirtualList } from '../virtual-list'
const emit=defineEmits(['close','changed']),directories=ref([]),directoryID=ref(''),selected=ref([]),selecting=ref(false),menu=ref(false),confirm=ref(false),busy=ref(false),panel=ref(null)
const directory=computed(()=>directories.value.find(d=>d.id===directoryID.value)),items=computed(()=>directory.value?.items||[])
const {shown,top,bottom,reset}=useVirtualList(items,panel,{rowHeight:84,window:true,resetToTop:true})
let anchor=-1,alive=true
const storage=d=>state.storages.find(s=>s.id===d?.storageId)
const pathParts=d=>(d?.pathLabel||d?.source||'/').split('/').filter(Boolean)
function clear(){selected.value=[];selecting.value=false;anchor=-1}
function choose(d){directoryID.value=d.id;menu.value=false;clear();nextTick(reset)}
function select(event,item){if(!selecting.value)return;const index=items.value.indexOf(item);if(event.shiftKey&&anchor>=0){selected.value=[...new Set([...selected.value,...items.value.slice(Math.min(anchor,index),Math.max(anchor,index)+1).filter(i=>!i.status).map(i=>i.id)])]}else{if(!item.status)selected.value=selected.value.includes(item.id)?selected.value.filter(id=>id!==item.id):[...selected.value,item.id];anchor=index}}
function context(event,item){selecting.value=true;select(event,item)}
function all(){const eligible=items.value.filter(i=>!i.status);selecting.value=true;selected.value=selected.value.length===eligible.length?[]:eligible.map(i=>i.id);anchor=-1}
function outside(event){if(!event.target.closest('.rename-history-panel,.history-actions,.history-directory-control,.modal')){clear();menu.value=false}}
function key(event){if(event.key==='Escape'&&!confirm.value){clear();menu.value=false}}
async function restore(){busy.value=true;const restoredDirectory=directory.value;try{const result=await api('/files/rename-restore','POST',{directoryId:directoryID.value,ids:selected.value});if(!alive)return;for(const item of result){const old=items.value.find(i=>i.id===item.id);if(old)Object.assign(old,item)}confirm.value=false;clear();emit('changed',result,restoredDirectory);notify(`恢复成功 ${result.filter(i=>i.status==='success').length} 项，失败 ${result.filter(i=>i.status==='failed').length} 项`,result.some(i=>i.status==='failed'))}catch(e){if(alive)notify(e.message,true)}finally{if(alive)busy.value=false}}
function parts(item,old){return old?changedNameParts(item.newName,item.name):changedNameParts(item.name,item.newName)}
onMounted(async()=>{document.addEventListener('click',outside);document.addEventListener('keydown',key);try{const result=await api('/files/rename-history');if(alive){directories.value=result;directoryID.value=result[0]?.id||''}}catch(e){if(alive)notify(e.message,true)}})
onUnmounted(()=>{alive=false;document.removeEventListener('click',outside);document.removeEventListener('keydown',key)})
</script>
<template>
 <section class="rename-history-page">
  <header class="task-heading history-heading"><button class="icon-btn" aria-label="返回命名工作台" :disabled="busy" @click="emit('close')"><Icon name="ArrowLeft" /></button><h2 class="module-title">历史命名记录</h2><div class="history-directory-control"><button class="history-directory-trigger" aria-label="选择历史目录" :disabled="busy" :aria-expanded="menu" @click.stop="menu=!menu"><ProviderIcon v-if="storage(directory)" :type="storage(directory).type" compact /><strong>{{storage(directory)?.name||'选择目录'}}</strong><VisitPath :parents="pathParts(directory).slice(0,-1)" :deepest="pathParts(directory).at(-1)||'根目录'" /><Icon name="ChevronDown" :size="16" /></button><div v-if="menu" class="history-directory-menu" role="listbox" aria-label="历史目录"><button v-for="d in directories" :key="d.id" role="option" :aria-selected="d.id===directoryID" @click.stop="choose(d)"><ProviderIcon :type="storage(d)?.type||'local'" compact /><strong>{{storage(d)?.name||'存储已移除'}}</strong><VisitPath :parents="pathParts(d).slice(0,-1)" :deepest="pathParts(d).at(-1)||'根目录'" /></button></div></div><div class="history-actions"><button class="btn" :disabled="busy||!items.length" @click="all"><Icon name="CheckCheck" />{{selected.length===items.filter(i=>!i.status).length&&selected.length?'全不选':'全选'}}</button><button class="btn primary" :disabled="busy||!selected.length" @click="confirm=true"><Icon name="RotateCcw" />恢复</button></div></header>
<section ref="panel" class="rename-history-panel"><div :style="{height:top+'px'}" /><article v-for="item in shown" :key="item.id" class="rename-history-row" :class="[item.status,{selected:selected.includes(item.id)}]" tabindex="0" @contextmenu.prevent="context($event,item)" @click="select($event,item)" @keydown.space.prevent="selecting=true;select($event,item)"><Icon v-if="selecting" :name="selected.includes(item.id)?'CircleCheck':'Circle'" class="history-check" /><div class="history-names"><div><small>原：</small><Icon :name="entryIcon({name:item.name,isDir:item.isDir})" :class="{'folder-color':item.isDir}" /><span><template v-for="(part,index) in parts(item,true)" :key="index"><mark v-if="part.changed">{{part.text}}</mark><template v-else>{{part.text}}</template></template></span></div><div><small>新：</small><Icon :name="entryIcon({name:item.newName,isDir:item.isDir})" :class="{'folder-color':item.isDir}" /><span><template v-for="(part,index) in parts(item,false)" :key="index"><mark v-if="part.changed">{{part.text}}</mark><template v-else>{{part.text}}</template></template></span></div></div><div class="history-result"><time>{{date(item.modified)}}</time><small v-if="item.status">{{item.status==='success'?'已恢复':item.error}}</small></div></article><div :style="{height:bottom+'px'}" /><p v-if="!items.length" class="small-empty">暂无历史记录</p><footer>{{items.length}} 项</footer></section>
 </section>
 <Modal v-if="confirm" compact confirmation title="恢复原名称" @close="!busy&&(confirm=false)"><div class="modal-body">确认恢复所选 {{selected.length}} 项的原名称？已改名、移动、删除或原名称被占用的项目不会覆盖。</div><footer class="modal-footer"><button class="btn primary" :disabled="busy" @click="restore">确认恢复</button><button class="btn" :disabled="busy" @click="confirm=false">取消</button></footer></Modal>
</template>
<style scoped>
.rename-history-row{user-select:none}
.rename-history-page{min-width:0;min-height:calc(100dvh - 80px);display:flex;flex-direction:column;padding-bottom:var(--workspace-end-gap)}.history-heading{align-items:center;gap:10px}.history-heading h2{font-size:16px;white-space:nowrap}.history-actions{margin-left:auto;display:flex;gap:8px;flex:none}.history-directory-control{position:relative;flex:1;min-width:0}.history-directory-trigger{display:flex;align-items:center;gap:8px;width:100%;height:36px;padding:5px 9px;border:1px solid var(--border);border-radius:8px;background:var(--input);color:var(--text);min-width:0}.history-directory-trigger strong{font-size:13px;flex:none;white-space:nowrap}.history-directory-menu{position:absolute;z-index:20;top:calc(100% + 8px);left:0;width:100%;box-sizing:border-box;padding:6px;background:var(--input);border:1px solid var(--border);border-radius:8px;box-shadow:var(--shadow)}.history-directory-menu button{display:flex;gap:8px;width:100%;align-items:center;min-width:0;padding:10px;border:0;border-radius:6px;background:none;color:var(--text);text-align:left}.history-directory-menu button:hover,.history-directory-menu [aria-selected=true]{background:var(--primary-soft)}.history-directory-menu strong{white-space:nowrap;font-size:13px}.history-directory-control :deep(.provider-icon){width:22px;height:22px;background:none;border:0;padding:0;flex:none}.rename-history-panel{flex:1;position:relative;border:1px solid var(--border);border-radius:8px;padding:10px 10px 26px;background:var(--surface);min-width:0}.rename-history-row{position:relative;display:flex;gap:10px;align-items:center;height:78px;margin-bottom:6px;padding:8px 12px;border:1px solid var(--border);border-radius:8px;background:var(--input)}.history-names{display:grid;gap:4px;flex:1;min-width:0}.history-names>div{display:flex;gap:6px;align-items:center;min-width:0}.history-names span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px}.history-names small{color:var(--muted);font-size:12px}.history-names svg{flex:none}.history-names mark{background:color-mix(in srgb,var(--red) 8%,transparent);color:var(--red);border-radius:3px}.history-result{display:grid;gap:4px;text-align:right;max-width:35%}.history-result time,.history-result small{font-size:12px;color:var(--muted)}.history-result small{overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.rename-history-row.selected{background:var(--primary-soft);border-color:var(--primary)}.rename-history-row.success{border-color:var(--green)}.rename-history-row.failed{border-color:var(--red)}.rename-history-panel footer{position:absolute;bottom:6px;left:14px;font-size:12px;color:var(--muted)}.history-check{color:var(--primary);flex:none}
.rename-history-page{padding-bottom:0}
.history-heading h2.module-title{font-size:15px}
.history-heading h2,.history-directory-trigger>svg{flex:none}
.history-directory-menu strong{flex:none}
@media(max-width:760px){.history-heading{display:grid;grid-template-columns:auto minmax(0,1fr) auto}.history-directory-control{grid-column:1/-1;grid-row:2}.history-actions{margin-left:0;grid-column:3;grid-row:1}.history-result{max-width:32%}.history-result time{font-size:11px}}
</style>
